OUT=ROOT/'geometry-course/textbook/data/vector-product-review.json'


def question(n,title,task,answer,hint,steps,views,checks,refs,*,part=None,note=None):
    entry=card(n,None,[291],task,answer,hint,steps,views,checks,refs,caption=note)
    m=entry['visualization']['model']
    for i,(view,source) in enumerate(zip(m['views'].values(),[views[0],*views,*views],strict=True)):
        suffix='__v'+str(i)
        view['highlightSegments']=[[a+suffix,b+suffix] for a,b in source[2]]+[seg for seg in view['segments'] if seg[1].startswith('head_')]
    return review_entry(entry,n,title,part=part)


def definitions():
    displaced=copy_figure('Векторы с различными началами',{'A':(0,0),'B':(3,0),'C':(0,2),'D':(2,4)},'AB CD','')
    views=[displaced,common_view('Перенеси обе стрелки в P',(3,0),(2,2)),common_view('Длины различны, направление совпало',(3,0),(5,0))]
    a=question(14,'Определи угол между векторами','Что означает «угол между ненулевыми a и b равен α»? Объясни, при каком расположении угол принимают равным нулю.',
        'Перенеси оба вектора из одной точки так, чтобы каждая стрелка сохранила длину и направление. Углом называют угол от 0° до 180° между образованными лучами. При сонаправленных ненулевых векторах лучи совпадают и угол равен нулю независимо от модулей.',
        'У двух заданных стрелок могут быть разные начала. Параллельного переноса каждой достаточно. Нулевой вектор направления не имеет.',[
        ('Отдели положение от направления','AB=(3;0), CD=(2;2) на первой схеме начинаются в разных точках. Для угла важны их направления, а не расстояние между A и C.','Обращать концы одной стрелки при переносе нельзя.'),
        ('Собери угол в P','После переноса из P одна стрелка идёт вправо, другая вверх и вправо под 45°. Поэтому исходный угол тоже 45°.','Сравни две стрелки, направленные от одного общего начала.'),
        ('Проверь крайний случай','При длинах 3 и 5 на одном луче угол 0°. При развороте второй стрелки он станет 180°.','Разные длины могут задавать одно и то же направление.')],views,[
        ('Сколько градусов между (3;0) и (2;2)?','45','У второй стрелки одинаковые горизонтальное и вертикальное смещения.'),('Каков угол между (3;0) и (5;0)?','0','Обе направлены вдоль положительной полуоси x.')],[109])
    views=[common_view('Пара (2;1), (−1;2)',(2,1),(-1,2)),common_view('Разворот второй стрелки',(2,1),(1,-2)),common_view('Одна координата изменена',(2,1),(1,2))]
    b=question(15,'Распознай перпендикулярные направления','Когда два ненулевых вектора называются перпендикулярными? Изменится ли перпендикулярность после обращения одного направления?',
        'Два ненулевых вектора перпендикулярны, если угол между их направлениями равен 90°. При развороте одного вектора прямой угол меняется на смежный с ним прямой, то есть остаётся равным 90°.',
        'Проверь угол после переноса в одно начало. Для ненулевых векторов дополнительный способ проверки — нулевое скалярное произведение.',[
        ('Сравни с поворотом на четверть оборота','Поворот (2;1) на 90° против часовой стрелки даёт (−1;2). Их направления перпендикулярны.','Перестановка координат при повороте сопровождается сменой знака у одной из них.'),
        ('Разверни одну стрелку','Вектор (1;−2) противоположен (−1;2). Теперь произведение (2;1)·(1;−2)=2−2=0, а обе длины положительны.','Смежный с прямым угол также прямой.'),
        ('Проверь похожую пару','В новой паре (2;1) и (1;2) произведение 4. Значит угол острый. Одной перестановки координат для прямого угла недостаточно.','Смотри, у какого из чисел стоит знак минус.')],views,[
        ('Каков угол после полного разворота второго перпендикулярного вектора?','90','Отними 90° от 180°.'),('Каково произведение (2;1) и (1;2)?','4','Сложи 2·1 и 1·2.')],[109,111])
    views=[data_pair('Длины 4 и 3, угол 60°',60,4,3),data_pair('Такие же длины при 120°',120,4,3),common_view('Вторая стрелка сократилась до нуля',(4,0),(0,0))]
    c=question(16,'Дай определение скалярного произведения','Как определяют a·b и что получает ученик в результате? Отдельно рассмотри случай нулевого вектора.',
        'Для двух ненулевых векторов a·b=|a||b| cos α, где α — угол между ними. Это число. Если один из векторов нулевой, скалярное произведение равно нулю без выбора направления для нулевого вектора.',
        'Обе длины неотрицательны, а косинус может иметь разные знаки. У скалярного результата нет направления.',[
        ('Подставь три величины','Длины 4,3 и угол 60° дают 4·3·1/2=6. Единицы исходных длин умножаются.','Произведение длин без косинуса дало бы 12 только при нулевом угле.'),
        ('Отследи знак','При 120° те же модули дают 4·3·(−1/2)=−6. Длины положительны, знак поменял косинус.','Оцени знак до вычисления.'),
        ('Проверь случай нулевой длины','Если b=0, результат 0. При этом невозможно построить направление b, поэтому для доказательства не делим на |b|.','Нулевое произведение при одном нулевом векторе не задаёт угол.')],views,[
        ('Чему равно произведение для 4, 3 и 120°?','-6','Умножь 12 на −1/2.'),('Чему равно (4;0)·(0;0)?','0','Один из двух векторов равен нулю.')],[109,110])
    return [a,b,c]


def signs():
    specs=[
      ('а','Нулевой результат','нулю','90°',90,60,180,0,3,-6,
       'При обеих положительных длинах произведение равно нулю ровно при cos α=0, то есть при α=90°. Нулевой вектор исключён условием.',
       'В первом рисунке стрелки перпендикулярны. Уже при угле 60° с теми же модулями произведение положительно.'),
      ('б','Положительный результат','положительно','0°≤α<90°',0,60,90,6,3,0,
       'Произведение положительно ровно при 0°≤α<90°. В эту группу входят сонаправленные ненулевые векторы с углом 0°.',
       'При совпадающих направлениях cos 0°=1, а при остром угле косинус по-прежнему положителен. Прямой угол уже не даёт положительного результата.'),
      ('в','Отрицательный результат','отрицательно','90°<α≤180°',180,120,90,-6,-3,0,
       'Произведение отрицательно ровно при 90°<α≤180°. Включаются противоположные направления с углом 180°.',
       'При противоположности направлений cos 180°=−1. Тупой угол 120° тоже даёт отрицательное значение, но при 90° оно равно 0.')]
    rows=[]
    for part,title,word,range_,one,two,three,result,second,third,explanation,reason in specs:
        task='В каком случае произведение двух ненулевых векторов '+('равно нулю' if part=='а' else word)+'? Укажи все подходящие углы, проверь границы.'
        hint='Две положительные длины сохраняют знак косинуса. Укажи, входит ли в подходящие углы 0°, 90° или 180°.'
        views=[data_pair(f'Первое направление: {one}°',one),data_pair(f'Сравни с {two}°',two),data_pair(f'Проверь угол {three}°',three)]
        rows.append(question(17,title,task,explanation,hint,[
          ('Найди знак, исходя из определения',f'Для длин 2 и 3 имеем a·b=6 cos α. При α={one}° получается {result}. {explanation}','Косинус берут от угла между направленными лучами.'),
          ('Проверь соседнюю конфигурацию',reason+f' На втором чертеже угол {two}° и произведение {second}.','Прямой угол разделяет положительные и отрицательные значения.'),
          ('Испытай границу',f'При величине {three}° и прежних длинах получается {third}. Полное условие для рассматриваемого знака: {range_}.','Запись строгого либо нестрогого неравенства у границы должна соответствовать значению косинуса.')],views,[
          (f'Чему равно произведение на чертеже с углом {two}°?',str(second),'Умножь 6 на косинус показанного угла.'),(f'Каково новое произведение при {three}°?',str(third),'Модули обеих стрелок остались 2 и 3.')],[110],part=part))
    return rows


def coordinates():
    views=[common_view('Стрелки с координатами (3;2) и (1;4)',(3,2),(1,4),projections=True),
           common_view('Поменяй знак у ординаты второй стрелки',(3,2),(1,-4),projections=True),
           common_view('Другая пара: (−2;3), (4;1)',(-2,3),(4,1),projections=True)]
    a=question(18,'Выведи координатную формулу','Докажи, что для a=(x₁;y₁), b=(x₂;y₂) верно a·b=x₁x₂+y₁y₂.',
        'Запишем |a−b|²=|a|²+|b|²−2a·b. Через координаты левая часть равна (x₁−x₂)²+(y₁−y₂)². Раскрывая квадраты и сокращая x₁²,y₁²,x₂²,y₂², получаем 2a·b=2x₁x₂+2y₁y₂. Формула верна и при нулевом векторе.',
        'В каждой разности перемножаются одноимённые компоненты. Коэффициент 2 перед произведением возникает в каждом квадрате разности.',[
        ('Сравни длины по двум признакам','У a=(3;2), b=(1;4) длины в квадрате 13 и 17, а |a−b|²=2²+(−2)²=8. Поэтому a·b=(13+17−8)/2=11.','Проверь также по компонентам: 3·1+2·4=11.'),
        ('Проведи сокращение в буквах','Квадраты отдельных компонент совпадают по обе стороны. Остаются только −2x₁x₂−2y₁y₂ и −2a·b. После деления видна требуемая формула. При b=(1;−4) результат 3−8=−5.','Нельзя складывать квадраты компонент вместо попарных произведений.'),
        ('Вычисли на новой паре','Для (−2;3) и (4;1) сумма произведений равна −8+3=−5. Это согласуется с тупым углом между их направлениями.','Число, которое получили, может быть отрицательным в отличие от квадрата длины.')],views,[
        ('Каково исходное произведение (3;2)·(1;4)?','11','Сложи три и восемь.'),
        ('Чему равно новое (−2;3)·(4;1)?','-5','Учитывай знак абсциссы −2.')],[110,111])
    views=[common_view('Прямой угол у пары (4;3) и (−3;4)',(4,3),(-3,4)),
           common_view('Один вектор удвоен',(4,3),(-6,8)),common_view('Измени ординату до 3',(4,3),(-3,3))]
    b=question(19,'Запиши координатный признак перпендикулярности','Каким равенством проверяется перпендикулярность двух ненулевых векторов с координатами (x₁;y₁), (x₂;y₂)? Докажи достаточность и необходимость.',
        'Для ненулевых векторов прямой угол равносилен равенству x₁x₂+y₁y₂=0. Если угол прямой, cos 90°=0, произведение и сумма равны нулю. Обратно, нулевая сумма даёт cos α=0 после деления на положительные длины, а в диапазоне 0°…180° это только 90°.',
        'Укажи обе стороны доказательства и объясни, почему разрешено деление на |a||b|.',[
        ('Проверь исходный пример','Для (4;3) и (−3;4) сумма −12+12=0, оба модуля 5. Значит их угол прямой.','Начни с того, что ни один из векторов не нулевой.'),
        ('Проверь масштаб','Если вторую стрелку удвоить, сумма становится −24+24=0. Произведение умножилось на 2, и прямой угол сохранился.','Положительное масштабирование не поворачивает стрелку.'),
        ('Измени только координату','Пусть вторая стрелка (−3;3). Получается −12+9=−3: это уже тупой угол. Чтобы сохранить прямой угол для (−3;y), нужно решить −12+3y=0 и вернуть y=4.','Одну координату нельзя менять независимо, если нужен фиксированный угол.')],views,[
        ('Каково исходное произведение после удвоения второго вектора?','0','Вычисли −24+24.'),('Какой y даёт перпендикулярность (4;3) и (−3;y)?','4','Приравняй −12+3y к нулю.')],[109,111])
    views=[common_view('Исходные векторы (2;0) и (3;4)',(2,0),(3,4)),
           common_view('Вертикальное отражение второй стрелки',(2,0),(-3,4)),common_view('Перемести обе стрелки в новые направления',(0,5),(4,3))]
    c=question(20,'Выведи косинус угла через координаты','Вырази cos α через координаты двух ненулевых векторов. Объясни, зачем в знаменателе нужны их длины.',
        'Из a·b=|a||b| cos α получаем cos α=(x₁x₂+y₁y₂)/(√(x₁²+y₁²)·√(x₂²+y₂²)). Знаменатель положителен, так как оба вектора ненулевые. Он устраняет влияние масштаба каждой стрелки.',
        'Числитель может менять знак. В знаменателе надо умножать длины, а не их квадраты или сумму длин.',[
        ('Вычисли и раздели','Для a=(2;0), b=(3;4) произведение 6, модули 2 и 5. Поэтому cos α=6/10=3/5.','Косинус должен попадать в отрезок от −1 до 1.'),
        ('Проверь отрицательный случай','Для b=(−3;4) его длина осталась 5. Произведение стало −6 и cos α=−3/5. Угол со стрелкой вправо стал тупым.','Знак отрицательного косинуса нельзя отбросить при извлечении длин.'),
        ('Смени оба направления','Для a=(0;5), b=(4;3) произведение 15, обе длины по 5. Получаем cos α=15/25=3/5.','Разные пары на плоскости могут образовывать один и тот же угол.')],views,[
        ('Каково произведение длин для исходной пары?','10','Умножь 2 на 5.'),('Каков числитель сокращённой дроби cos α=…/5 у пары (0;5), (4;3)?','3','Сократи 15/25.')],[110,111])
    return [a,b,c]


def laws():
    def model(label,a,b,c):
        return copy_figure(label,{'O':(0,0),'A':a,'B':b,'C':c,'S':(b[0]+c[0],b[1]+c[1])},'OA OB OC OS','BS CS')
    views=[model('Распределение по двум слагаемым',(2,1),(1,2),(3,-1)),
           model('Умножь a на −2',(-4,-2),(1,2),(3,-1)),
           model('Измени последнее слагаемое',(2,1),(1,2),(-1,2))]
    entry=question(21,'Обоснуй свойства скалярного произведения','Сформулируй и докажи свойства скалярного произведения. Включи скалярный квадрат, перестановку векторов, распределение по сумме и числовой множитель.',
        'Имеем a·a=|a|²≥0 и равенство возможно точно при a=0. Перестановка a и b сохраняет сумму x₁x₂+y₁y₂. При сложении b+c координаты складываются, и после раскрытия a·(b+c)=a·b+a·c. Для любого действительного k линейность каждой компоненты даёт (ka)·b=k(a·b)=a·(kb).',
        'Доказывай в компонентах. Используй свойства обычных чисел для каждой из двух сумм, затем собери два скалярных произведения.',[
        ('Проверь скалярный квадрат и симметрию','Возьми a=(2;1), b=(1;2), c=(3;−1). Тогда a·a=5 и a·b=b·a=4. Формула a·a=x²+y² сразу даёт условие равенства нулю.','Квадраты действительных чисел неотрицательны.'),
        ('Раскрой левую часть','b+c=(4;1), поэтому a·(b+c)=9. Справа a·b+a·c=4+5=9. При замене a на −2a обе части умножаются на −2 и становятся −18. Для произвольных компонент работает тот же распределительный закон.','При отрицательном множителе произведение меняет знак.'),
        ('Замени одно слагаемое','При c=(−1;2) сумма b+c=(0;4), a·(b+c)=4. Отдельно a·b=4 и a·c=0. Вектор c перпендикулярен a, поэтому его вклад нулевой.','Проверяй общую формулу при положительном, отрицательном и нулевом вкладе.')],views,[
        ('Чему равно (−2a)·(b+c) при исходных b и c?','-18','Умножь первоначальную девятку на −2.'),('Чему равно a·(b+c) после замены c на (−1;2)?','4','Новое c даёт нулевой вклад.')],[110,111,112],note='OA=a, OB=b, OC=c и OS=b+c. Короткую или повернутую стрелку можно сравнить по единичному отрезку UV.')
    return entry


def diameter():
    def drawing(label,m):
        return copy_figure(label,{'A':(-5,0),'B':(5,0),'O':(0,0),'M':m,'_upper':(0,5),'_lower':(0,-5)},'MA MB','AB')
    views=[drawing('Точка M=(3;4) на окружности',(3,4)),drawing('Другая точка M=(0;5) на окружности',(0,5)),drawing('Точка M=(3;3) внутри окружности',(3,3))]
    entry=question(22,'Примени произведение в геометрической задаче','Приведи пример геометрического доказательства с помощью скалярного произведения. Докажи, что диаметр AB из любой другой точки его окружности виден под прямым углом.',
        'Пусть центр O=(0;0), A=(−r;0), B=(r;0), M=(x;y). Тогда MA·MB=(−r−x)(r−x)+(−y)²=x²+y²−r². Точка на окружности удовлетворяет x²+y²=r², поэтому произведение равно 0. При M, отличной от A,B, обе стрелки ненулевые, значит ∠AMB=90°.',
        'Нужны две стрелки с началом M. Положение M на окружности выражается равенством x²+y²=r²; переход к углу требует ненулевых длин.',[
        ('Проверь первый чертёж','При r=5, M=(3;4) имеем MA=(−8;−4) и MB=(2;−4). Произведение −16+16=0. Вершина прямого угла — M.','Начало вектора при вычислении координат всегда вычитается из его конца.'),
        ('Докажи для любой точки окружности','Раскрой (−r−x)(r−x)+y²: получится x²+y²−r². При M=(0;5) в нашем примере это снова 0. При M=A или M=B одна стрелка нулевая, поэтому такие точки надо исключить.','Числовые примеры иллюстрируют, а равенство для x,y доказывает.'),
        ('Проверь точку внутри','При M=(3;3) получаем MA·MB=9+9−25=−7. Угол между ненулевыми стрелками оказался тупым. Так видно, где использовалась принадлежность окружности.','Сравни квадрат расстояния до O с квадратом радиуса.')],views,[
        ('Каково произведение MA·MB при M=(0;5) и r=5?','0','Точка лежит на окружности.'),('Каково произведение при новой внутренней точке M=(3;3)?','-7','Из квадрата расстояния 18 вычти 25.')],[109,110,111],note='AB — диаметр длины 10, O — его середина. Обе стрелки начинаются в M. UV — единичный отрезок.')
    model=entry['visualization']['model']
    for i,view in enumerate(model['views'].values()):
        suffix='__v'+str(i)
        view['points']=[p for p in view['points'] if not p.startswith('_')]
        view['circles']=[{'center':'O'+suffix,'through':'B'+suffix}]
    return entry


def build():
    return {'bookId':BOOK,'lessons':definitions()+signs()+coordinates()+[laws(),diameter()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    output=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==output
    else:OUT.write_text(output)
